
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_q1d_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_q1d", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.169495781394609e+00, -4.080145200886944e+00, -3.953968827314740e+00, -3.776982496945935e+00, -3.530673187719240e+00, -3.190309944696778e+00, -2.720379208883242e+00, -2.064400818463171e+00, -1.180413292860208e+00, -3.947802150432349e-01, -2.588491092126595e-01, -5.901019909907660e-01, -5.939950454181733e-01, -4.384581847757684e-01, -1.892045808635570e-01, -1.890425644687281e-02, -6.450766235955196e-04, -2.100377256815027e-05, -2.120291647475234e-07, -3.080322332875353e-10]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


